def count_set_bits(n):
    m = n
    count = 0
    while m:
        if m & 1:
            count += 1
        m = m >> 1
    return count

def check_excitation_possible(excit, det, ref):
    annihilation = excit & ref
    creation = excit - (excit & ref)
    det_annih = (det ^ ref) & ref
    det_creation = (det ^ ref) - ((det ^ ref) & ref)    
    if (creation & det_creation != 0 or annihilation & det_annih != 0):
        possible = False
    else:
        possible = True
    return possible
def check_deexcitation_possible(excit, det, ref):
    creation = excit & ref
    annihilation = excit - (excit & ref)
    det_annih = (det ^ ref) & ref
    det_creation = (det ^ ref) - ((det ^ ref) & ref)    
    possible = True
    for n in range(64):
        if (annihilation & (1<<n) and not det_creation & (1<<n)):
            possible = False
            break
        if (creation & (1<<n) and det & (1<<n)):
            possible = False
            break
    return possible   
def excite(det, excit, ref):
    sign = 1
    new_det = det
    det_annih = (det ^ ref) & ref
    det_creation = (det ^ ref) - det_annih

    for i in range(64):
        mask = (~0)<<i+1
        if excit & 1<<i:
            if ref & 1<<i:
            # If exciting from orbital i, permute with all annihilation of
            # higher index and add creation
               new_det = new_det & ~(1<<i)
               permute = mask & det_annih
               permute = permute ^ det_creation
            else:
            # If exciting into orbital i, permute with every creation of lower index
               new_det = new_det | (1<<i)
               permute =  ~mask & det_creation 
               permute = permute & ~(1<<i)
            if (count_set_bits(permute)%2 == 1):
                sign = -sign
    return new_det, sign

def deexcite(det, excit, ref):
    sign = 1
    new_det = det
    det_annih = (det ^ ref) & ref
    det_creation = (det ^ ref) - det_annih
    excit_annih = excit & ~ref
    for i in range(63, -1, -1):
        mask = ~0<<i+1
        if excit & 1<<i:
            if not (ref & 1<<i):
               #If exciting from i, permute with all creation of lower index
               new_det = new_det & ~(1<<i)
               permute =  ~mask & det_creation
               excit_swap = ~mask & excit_annih
               permute = permute ^ excit_swap
               permute = permute & ~(1<<i)
            else:
               #If exciting into i, permute with all creation operators and annihilation of higher index
               new_det = new_det | (1<< i)
               permute = mask & det_annih
               permute = permute ^ det_creation
            if (count_set_bits(permute)%2 == 1):
               sign = -sign
            det_annih = (new_det ^ ref) & ref
            det_creation = (new_det ^ ref) & ~ref
    return new_det, sign

def excit_to_det(det, ref):
    excit = det^ref
    excit_level = count_set_bits(excit)/2
    nannih = excit_level
    ncreate = excit_level

    sign = 1

    for ibit in range(64):
        if (ref & 2**ibit):
            if (excit & 2**ibit):
                nannih -= 1
            elif (nannih+ncreate)%2 == 1:
                sign = -sign
        elif excit & 2**ibit:
            ncreate -= 1
    return sign

def get_proj_energy(final_contrib, keys, hmat):
    normalisation = 0
    proj_energy = 0
    normalisation = final_contrib[1023]
    for j in keys:
        if j in final_contrib:
            proj_energy += final_contrib[j]*hmat[j][1023]
    proj_energy /= normalisation
    return proj_energy

def get_var_energy_and_resid_proj(total_contrib, keys, keys2, hmat, proj_energy):
    residuals_proj_it = {}
    rp_contrib = {17403:{}, 33783:{}}
    var_energy = 0
    normalisation = 0
    for key1 in keys2:
        normalisation +=total_contrib[key1]**2
        residual_proj = 0
        for key2 in keys2:  
            if key1 in hmat and key2 in hmat: 
                var_energy += total_contrib[key1]*total_contrib[key2]*hmat[key1][key2]
            if key1 in keys:
                if key1 == key2:
                   residual_proj += total_contrib[key2]*(hmat[key1][key2]-proj_energy)
                else:
                   residual_proj += total_contrib[key2]*(hmat[key1][key2])
        if key1 in keys:
            residuals_proj_it[key1] = residual_proj
    var_energy /= normalisation
    return var_energy, residuals_proj_it

def get_ci_wfn(coeffs, excitors, keys,s):
    keys2=keys.copy()
    ts = coeffs
    contributions = {}
    final_contrib ={}
    for i in range(s+1):
        final_contrib[i] = {}
        contributions[i] = {} 
    contributions[0][1023] = ts[1023]
    final_contrib[0][1023] = ts[1023] 
    
    for i in keys[1:]:
        contributions[1][i] = ts[i]
        final_contrib[1][i] = contributions[1][i]/math.factorial(1)*excit_to_det(i, 1023)
    for i in range(2,s+1):
        for det in contributions[i-1]:
            for excit in keys[1:]:
                possible = check_excitation_possible(excitors[excit], det, 1023)
                if possible:
                    new_det, sign = excite(det, excitors[excit], 1023)
                    if new_det not in keys2:
                        keys2.append(new_det)
                    if new_det in contributions[i]:
                        contributions[i][new_det] += contributions[i-1][det]*ts[excit]*sign
                    else:
                        contributions[i][new_det] = contributions[i-1][det]*ts[excit]*sign
                possible = check_deexcitation_possible(excitors[excit], det, 1023)
                if possible:
                    new_det, sign = deexcite(det, excitors[excit], 1023)
                    if new_det not in keys2:
                        keys2.append(new_det)
                    if new_det in contributions[i]:  
                        contributions[i][new_det] -= contributions[i-1][det]*ts[excit]*sign
                    else:
                        contributions[i][new_det] = -contributions[i-1][det]*ts[excit]*sign
        for j in contributions[i]:
            final_contrib[i][j] = contributions[i][j]/math.factorial(i)*excit_to_det(j, 1023)
    total_contrib = {}

    for key in keys2:
        total_contrib[key] = 0
        for i in final_contrib:
            if key in final_contrib[i]:
                total_contrib[key] += final_contrib[i][key]
    return total_contrib
